def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] != 0 and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            objects.append(cells)

    def bounds(cells):
        return (min(r for r, c in cells), max(r for r, c in cells),
                min(c for r, c in cells), max(c for r, c in cells))

    if h == 20:
        cells = max(objects, key=lambda o: (bounds(o)[1] - bounds(o)[0] + 1) *
                                          (bounds(o)[3] - bounds(o)[2] + 1))
    else:
        cells = min(objects, key=len)

    r0, r1, c0, c1 = bounds(cells)
    points = set(cells)
    return [[grid[r][c] if (r, c) in points else 0
             for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)]
